INSERT INTO categories (id,name,description,active) VALUES (1,'Limits Risk','Maneuvers through complex situations and anticipates risks, while charting a path that avoids negative outcomes and achieves solutions with appropriate governance.',1),(2,'Embraces Agility','Navigates changing situations and priorities. Thrives in change, anticipates and seizes opportunities, and adjusts behavior to empower teams.',1),(3,'Achieves Excellence','Takes ownership and applies fiscal accountability and sound judgement in managing resources in order to achieve the best project possible outcomes.',1),(4,'Develops Relationships','Builds strong relationships, creates safe spaces for diverse perspectives, and aligns the drivers of motivation with organisational priorities to promote productivity and build cohesion.',1),(5,'Sets Purpose','Aligns diverse perspectives and voices, creating a shared vision, which instills confidence and inspires others. Connects stories and datapoints. Communicates results and creates a clear call to action.',1);
--> statement-breakpoint
INSERT INTO capabilities (id,name,description,active) VALUES (1,'Communicates Clarity','Creates shared understanding and meaning by delivering concise and well articulated communications to diverse groups',1),(2,'Creates Alliances','Establishes relationships with key partners and builds and maintains engagement',1),(3,'Demonstrates Empathy','Fosters collaboration by listening and withholding judgement to create safe spaces to share perspectives',1),(4,'Develops Talent','Actively supports self and team growth through investing in formal and informal development methods',1),(5,'Drives Performance and Productivity','Navigates competing priorities, aligns objectives, and defines tasks and milestones to achieve organizational goals',1),(6,'Embraces Diversity','Brings different perspectives to the table, confronts bias and addressing systemic barriers to inclusion and accessibility',1),(7,'Empowers Team Effectiveness','Creates resilient ecosystems by aligning and connecting team members through shared goals and resources',1),(8,'Establishes Governance','Works with stakeholders to ensure accountability, ethical behaviour, fairness and transparency',1),(9,'Evolves With Technology','Embraces the use of new technologies to improve efficiency, spur transformational change and seize opportunities',1),(10,'Exercises Sound Judgement/Consulting','Makes decisions by using a balanced mix of analysis, big picture thinking and expertise, while maintaining objectivity',1),(11,'Focuses on Customers','Prioritizes client satisfaction by anticipating needs and listening without being defensive',1),(12,'Influences Responsibly','Uses compelling arguments and a deep understanding of stakeholder motivations to gain support responsibly and ethically',1),(13,'Inspires Others','Builds loyalty by clearly articulating a compelling vision the sincere intention of making a positive difference.',1),(14,'Leads and Embraces Change','Scans for opportunities to drive positive change and overcome barriers by remaining open to new ideas and approaches',1),(15,'Manages Risk','Forecasts and Evaluates risk and identifies processes to mitigate the negative impacts while attaining objectives',1),(16,'Moves Data to Action','Uses market research and other analysis to build cohesive stories that connect the dots between data and calls to action',1),(17,'Navigates Policies and People','Leverages a deep understanding of how organizations work to achieve objectives through tactful and savvy approaches',1),(18,'Plans for the Future','Anticipates emerging trends, organizational needs and emerging pitfalls to build breakthrough strategies',1),(19,'Reasons Critically and Solves Problems','Conducts root cause analysis to understand the problem and identify the practical and effective solutions',1),(20,'Resolves Conflicts','Reads situations in order to find common ground, promote mutual understanding and settle disputes equitably',1),(21,'Scans for Politicals and Internal Impacts','Uses understanding of broad political, social and economic factors to maneuver through complex situations',1),(22,'Takes Ownership','Takes responsibility, faces criticism with courage, confronts problems and follows through on commitments',1),(23,'Thrives in Chaos','Maintains productivity in the face of change by adapting priorities and behavior',1);
--> statement-breakpoint
